mapper.select:
SELECT p.product_id AS productId, p.producer_id AS producerId, p.base_category_id AS baseCategoryId, p.name AS name, p.summary AS summary, p.main_image AS mainImage, p.status AS status, p.created_date AS createdDate, p.updated_date AS updatedDate,
d.detail_id AS detailId, d.grade AS grade, d.unit_name AS unitName, d.price AS price, d.stock_qty AS stockQty, d.origin_region AS originRegion, d.harvest_date AS harvestDate, d.expire_date AS expireDate, d.detail_desc AS detailDesc, d.created_date AS detailCreatedDate, d.updated_date AS detailUpdatedDate
FROM product p LEFT JOIN product_detail d ON p.product_id = d.product_id WHERE p.product_id = #{value}
